import * as T from './vendor/three.module.js';
const v=(x,y,z)=>new T.Vector3(x,y,z);
const solid=(c,m=.24,r=.49)=>new T.MeshStandardMaterial({color:c,metalness:m,roughness:r});
const dark=solid('#26303a'),silver=solid('#c4cdd0',.48,.35),white=solid('#d8d4c7',.25,.52),ivory=solid('#f4ede0',.22,.58),bronze=solid('#92764d',.43),gold=solid('#c3a16b',.47),black=solid('#0f171d'),amber=solid('#f0a044'),navy=solid('#223853'),steel=solid('#6f8489',.4),aqua=solid('#74b3af'),blue=solid('#3d77ad');
const copper=solid('#b87c50',.4),lit=solid('#b3ffe7');lit.emissive.setHex(0x42b594);lit.emissiveIntensity=.65;
const cellMat=solid('#fff',.20,.43),finMat=solid('#fff',.28,.58),foilMat=solid('#fff',.37,.52);
const boxG=new T.BoxGeometry(1,1,1);boxG.userData.shared=true;
const sharedMaterials=[dark,silver,white,ivory,bronze,gold,black,amber,navy,steel,aqua,blue,copper,lit,cellMat,finMat,foilMat];
for(const material of sharedMaterials)material.userData.shared=true;
const cylG=new Map();
function cylinderGeom(a,b,n,open){const key=[a,b,n,open].join('/');if(!cylG.has(key)){const g=new T.CylinderGeometry(a,b,1,n,1,open);g.userData.shared=true;cylG.set(key,g);}return cylG.get(key);}
function obj(p,g,m,x,y,z,id){const a=new T.Mesh(g,m);a.position.set(x,y,z);if(id)a.userData.part=id;p.add(a);return a;}
function box(p,x,y,z,w,h,d,m,id){let a=obj(p,boxG,m,x,y,z,id);a.scale.set(w,h,d);return a;}
function cyl(p,x,y,z,rTop,rBot,height,m,id,n=16,open=false){const radius=Math.max(rTop,rBot,.00001),geom=cylinderGeom(+(rTop/radius).toFixed(5),+(rBot/radius).toFixed(5),n,open);let a=obj(p,geom,m,x,y,z,id);a.scale.set(radius,height,radius);return a;}
const sphereG=new T.SphereGeometry(1,22,12);sphereG.userData.shared=true;
function ell(p,x,y,z,a,b,c,m,id){let o=obj(p,sphereG,m,x,y,z,id);o.scale.set(a,b,c);return o;}
function pipe(p,a,b,r,m,id){const d=b.clone().sub(a),c=a.clone().add(b).multiplyScalar(.5);let o=cyl(p,c.x,c.y,c.z,r,r,d.length(),m,id,6);o.quaternion.setFromUnitVectors(v(0,1,0),d.normalize());return o;}
function strokes(p,segments,color,id,opacity=1){let points=[];for(const [a,b] of segments)points.push(...a,...b);const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(points,3));const lines=new T.LineSegments(geo,new T.LineBasicMaterial({color,opacity,transparent:opacity<1}));if(id)lines.userData.part=id;p.add(lines);return lines;}
function canvas(w,h){let c=document.createElement('canvas');c.width=w;c.height=h;return[c,c.getContext('2d')];}
function tex(c){let t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.anisotropy=8;return t;}
function textures(){if(cellMat.map)return;let [c,g]=canvas(768,384);g.fillStyle='#142034';g.fillRect(0,0,c.width,c.height);const nx=12,ny=6,sx=c.width/nx,sy=c.height/ny;
for(let col=0;col<nx;col++)for(let row=0;row<ny;row++){let x=col*sx+1.9,y=row*sy+1.9,k=(col*13+row*29)%17;let gradient=g.createLinearGradient(x,y,x+sx,y+sy);gradient.addColorStop(0,`rgb(${27+k},${52+k},${86+k*2})`);gradient.addColorStop(.52,`rgb(${20+k},${40+k},${76+k*2})`);gradient.addColorStop(1,`rgb(${34+k},${64+k},${101+k*2})`);g.fillStyle=gradient;g.beginPath();g.moveTo(x+4,y);g.lineTo(x+sx-8,y);g.lineTo(x+sx-4,y+4);g.lineTo(x+sx-4,y+sy-8);g.lineTo(x+sx-8,y+sy-4);g.lineTo(x+4,y+sy-4);g.lineTo(x,y+sy-8);g.lineTo(x,y+4);g.closePath();g.fill();g.strokeStyle='rgba(133,163,182,.44)';g.lineWidth=.75;g.stroke();g.fillStyle='rgba(167,189,216,.30)';for(let i=1;i<15;i++)g.fillRect(x+1,y+i*(sy-4)/15,sx-6,.7);g.fillStyle='rgba(186,177,149,.65)';g.fillRect(x+sx*.32,y+1,1.2,sy-6);g.fillRect(x+sx*.68,y+1,1.2,sy-6);}
cellMat.map=tex(c);[c,g]=canvas(512,256);g.fillStyle='#d9d8cf';g.fillRect(0,0,512,256);for(let i=0;i<=64;i++){g.fillStyle=i%8===0?'#747d7c':'#b1b8b3';g.fillRect(i*8,0,i%8===0?1.8:.8,256);}for(let j=0;j<4;j++){g.fillStyle='#919792';g.fillRect(0,j*64,512,.9);}finMat.map=tex(c);[c,g]=canvas(256,128);g.fillStyle='#ac884d';g.fillRect(0,0,256,128);let seed=24;const rand=()=>((seed=1664525*seed+1013904223>>>0)/4294967296);let pts=[];for(let j=0;j<=8;j++){let row=[];for(let i=0;i<=16;i++)row.push([i*16+(rand()-.5)*12,j*16+(rand()-.5)*13]);pts.push(row);}for(let j=0;j<8;j++)for(let i=0;i<16;i++)for(let k=0;k<2;k++){let tri=k?[pts[j][i],pts[j+1][i],pts[j+1][i+1]]:[pts[j][i],pts[j][i+1],pts[j+1][i+1]],a=rand()*.35;g.fillStyle=`rgba(${rand()<.5?'30,22,10':'255,238,165'},${a})`;g.beginPath();tri.forEach(([x,y],n)=>n?g.lineTo(x,y):g.moveTo(x,y));g.closePath();g.fill();}foilMat.map=tex(c);}
function face(p,x,y,z,w,d,m,id){const a=obj(p,new T.PlaneGeometry(w,d),m,x,y,z,id);a.rotation.x=-Math.PI/2;a.userData.texturePlane=true;return a;}
function join(p,x,y,z,id){let g=new T.Group();g.position.set(x,y,z);g.userData.part=id;p.add(g);return g;}
function labelPlate(p,x,y,z,w,d,caption){const [c,g]=canvas(512,112);g.fillStyle='#e3e1d7';g.fillRect(0,0,512,112);g.fillStyle='#26343b';g.font='bold 60px monospace';g.fillText(caption,18,74);g.fillStyle='#bd6b21';g.fillRect(0,0,7,112);let m=solid('#fff');m.map=tex(c);return face(p,x,y,z,w,d,m,'structure');}
export function makeCraft(h){textures();const root=new T.Group(),internal=new T.Group(),skin=new T.Group();root.add(skin,internal);let bw=h.bodyWidthM,bh=h.bodyHeightM,bl=h.bodyLengthM;const panelL=h.wingLengthM,panelW=h.wingWidthM,radL=h.radiatorLengthM,radW=h.radiatorWidthM;let wings=[],rads=[],cmgs=[],cells=[],leds=[],plumes=[];const gleam=[];const w=bw,hgt=bh,l=bl,beam=Math.min(w,hgt)*.052;const y0=hgt*.5;
// Rigid flight bus: spine, structural bays, blankets and removable access covers.
box(root,0,-y0*.88,0,w*.95,beam*1.5,l,silver,'structure');box(root,0,-y0*.74,0,w*.90,beam*.6,l*.96,black,'structure');box(skin,0,0,0,w*.90,hgt*.91,l*.96,black,'structure');
for(let side of [-1,1])for(let y of [-1,1])box(root,side*w*.48,y*y0,0,beam,beam,l*1.025,white,'structure');
for(let iz=0;iz<=5;iz++){const z=-l*.50+iz*l*.2;for(let side of [-1,1])box(root,side*w*.48,0,z,beam, hgt,beam,silver,'structure');box(root,0,y0,z,w,beam,beam,silver,'structure');box(root,0,-y0,z,w,beam,beam,silver,'structure');if(iz<5){let bz=z+l*.10;for(let side of [-1,1]){let a=box(skin,side*w*.469,0,bz,beam*.26,hgt*.83,l*.176,iz===2?foilMat:iz%2?white:ivory,'structure');const x=side*w*.483;for(let k=0;k<4;k++)box(skin,x,y0*.5-k*hgt*.13,bz,beam*.11,beam*.12,l*.10,steel,'structure');pipe(skin,v(x,-y0*.81,z+l*.015),v(x,y0*.81,z+l*.18),beam*.16,bronze,'structure');}box(skin,0,y0*.985,bz,w*.91,beam*.42,l*.174,iz%2?foilMat:white,'structure');}}
for(let s of [-1,1]){box(skin,0,0,s*l*.492,w*.88,hgt*.82,beam,foilMat,'structure');for(let j of [-1,1]){pipe(skin,v(j*w*.46,-y0*.93,s*l*.512),v(-j*w*.46,y0*.93,s*l*.512),beam*.31,ivory,'structure');}}
labelPlate(skin,0,y0+beam*.4,-l*.2,w*.65,l*.085,'ODC / 01');
// Four articulated solar wings. Each wing has three folding leaves, cell strings and a visible wiring spine.
const mountZ=Math.max(l*.28,panelW*.73);for(let side of [-1,1])for(let aft of [-1,1]){const z=aft*mountZ;const y=beam*.2;for(const a of [-1,1])pipe(root,v(side*w*.47,a*y0*.60,aft*l*.43),v(side*w*.57,a*y*.85,z),beam*.29,silver,'structure');
const pivot=join(root,side*w*.50,y0*.02,z,'solar');box(pivot,side*w*.20,0,0,w*.40,beam*1.25,beam*1.8,steel,'solar');for(let ring=-1;ring<=1;ring++){let a=cyl(pivot,side*w*(.24+ring*.06),0,0,beam*1.25,beam*1.25,beam*.42,ring===0?gold:silver,'solar');a.rotation.z=Math.PI/2;}
const fold=join(pivot,side*w*.43,0,0,'solar');const bank=join(fold,0,0,0,'solar');const leaves=[];let previous=bank;wings.push({fold,bank,side,aft,leaves});
const seg=panelL/3, depth=Math.max(beam*.42,.038);for(let tile=0;tile<3;tile++){const leaf=join(previous,side*(tile?seg:0),0,0,'solar');leaves.push(leaf);previous=leaf;const x=side*.5*seg;box(leaf,x,0,0,seg*.978,depth,panelW,bronze,'solar');face(leaf,x,depth*.51,0,seg*.97,panelW*.968,cellMat,'solar');const lower=face(leaf,x,-depth*.51,0,seg*.97,panelW*.968,cellMat,'solar');lower.rotation.x=Math.PI/2;
const grid=[];for(let k=1;k<=5;k++)grid.push([[x-seg*.477+k*seg*.159,depth*.54,-panelW*.48],[x-seg*.477+k*seg*.159,depth*.54,panelW*.48]]);for(let k=1;k<3;k++)grid.push([[x-seg*.48,depth*.54,-panelW*.48+k*panelW*.32],[x+seg*.48,depth*.54,-panelW*.48+k*panelW*.32]]);strokes(leaf,grid,'#bdab84','solar',.37);
for(let q of [-1,1])box(leaf,x,-depth*.4,q*panelW*.49,seg,depth*.86,Math.max(depth*.35,.019),silver,'solar');box(leaf,x,-depth*.85,0,seg,depth,depth*.82,silver,'solar');}
pipe(pivot,v(side*w*.1,-beam,0),v(side*w*.44,-beam*.15,panelW*.26),beam*.33,gold,'solar');}
// Two double-sided radiator banks run fore and aft from independent roots.
for(let sign of [-1,1]){const pivot=join(root,0,-y0*.45,sign*l*.50,'radiator');const bank=join(pivot,0,0,0,'radiator');rads.push({bank,sign});const stem=w*.35;box(bank,0,0,sign*stem*.5,beam*1.65,beam,stem,steel,'radiator');for(let k=0;k<3;k++){let z=sign*(stem+(k+.5)*radL/3),wid=radW;box(bank,0,0,z,wid,beam*.49,radL/3*.98,steel,'radiator');face(bank,0,beam*.257,z,wid*.981,radL/3*.961,finMat,'radiator');let f=face(bank,0,-beam*.257,z,wid*.981,radL/3*.961,finMat,'radiator');f.rotation.x=Math.PI/2;let grid=[];for(let j=1;j<10;j++)grid.push([[-wid*.49+j*wid*.098,beam*.262,z-radL*.158],[-wid*.49+j*wid*.098,beam*.262,z+radL*.158]]);strokes(bank,grid,'#8a9799','radiator',.53);for(let x of [-1,1])box(bank,wid*.49*x,0,z,beam*.20,beam*.55,radL/3,white,'radiator');}for(let s of [-1,1])pipe(bank,v(s*w*.20,0,0),v(s*radW*.45,0,sign*stem),beam*.25,copper,'radiator');}
// Tank pair with external bands, pressure domes and dedicated feed lines.
const tankR=Math.min(w*.24,Math.cbrt(Math.max(.02,h.tankVolumeL/1000)/2/(4*Math.PI/3))*.9);for(let sign of [-1,1]){let x=sign*(w*.50+tankR*.68),uc=join(root,x,-hgt*.21,0,'propellant');ell(uc,0,0,0,tankR,tankR,tankR*1.32,gold,'propellant');for(let z of [-.49,.49]){let ring=new T.Mesh(new T.TorusGeometry(tankR*.93,beam*.13,5,20),dark);ring.position.z=z*tankR;uc.add(ring);}let fluid=ell(uc,0,0,0,tankR*.92,tankR*.92,tankR*1.22,sign<0?blue:copper,'propellant');fluid.visible=false;cells.push({fluid,tank:uc.children[0],sign});pipe(uc,v(0,0,-tankR*1.29),v(-sign*tankR*1.2,-beam,-l*.45),beam*.21,copper,'propellant');}
// Reflector is a shallow paraboloid with crossed support rods and a feed horn.
const dishD=Math.max(.3,h.input.kaDishM),base=join(root,w*.16,y0+beam,-l*.35,'communications');cyl(base,0,beam*.6,0,dishD*.18,dishD*.24,beam*1.3,steel,'communications');const dish=join(base,0,beam*2,0,'communications');let parab=[];for(let j=0;j<=10;j++){const r=dishD*.5*j/10;parab.push(new T.Vector2(r,(r/dishD)**2*dishD*.65));}let dmat=solid('#dcdacb',.55,.38);dmat.side=T.DoubleSide;obj(dish,new T.LatheGeometry(parab,36),dmat,0,0,0,'communications');const rim=new T.Mesh(new T.TorusGeometry(dishD*.499,Math.max(.014,dishD*.014),5,40),bronze);rim.rotation.x=Math.PI/2;rim.position.y=dishD*.162;dish.add(rim);for(let j=0;j<3;j++){let a=j*2*Math.PI/3;pipe(dish,v(dishD*.44*Math.cos(a),dishD*.12,dishD*.44*Math.sin(a)),v(0,dishD*.37,0),dishD*.013,steel,'communications');}cyl(dish,0,dishD*.37,0,dishD*.035,dishD*.063,dishD*.10,gold,'communications');
const optic=join(root,-w*.2,y0+beam*1.8,l*.35,'communications');let ap=Math.max(.15,h.input.opticalApertureM);cyl(optic,0,ap*.45,0,ap*.68,ap*.8,ap,ivory,'communications');cyl(optic,0,ap*.98,0,ap*.63,ap*.63,beam*.2,black,'communications');cyl(optic,0,ap*1.01,0,ap*.46,ap*.46,beam*.12,blue,'communications');const patches=[-1,1].map(side=>box(skin,side*w*.49,y0*.52,l*.3,beam*.35,hgt*.14,w*.21,bronze,'communications'));
// Core hardware remains inside its flight mounts; removing the bus shell reveals the processor and fluid paths.
for(let s of [-1,1]){const rack=join(internal,s*w*.235,0,0,'compute');box(rack,0,-hgt*.04,0,w*.40,hgt*.74,l*.64,navy,'compute');for(let k=0;k<7;k++){const y=-hgt*.34+k*hgt*.10;box(rack,0,y,0,w*.42,beam*.32,l*.66,ivory,'compute');for(let j=0;j<4;j++){let z=(j-1.5)*l*.15;box(rack,s*w*.22,y+beam*.49,z,beam*.36,beam*.53,l*.095,black,'compute');const lamp=box(rack,s*w*.24,y+beam*.52,z+l*.037,beam*.09,beam*.18,beam*.2,lit,'compute');leds.push(lamp);}}for(let z of [-1,1])pipe(internal,v(s*w*.43,-hgt*.33,z*l*.33),v(s*w*.43,hgt*.38,z*l*.33),beam*.38,copper,'compute');}
for(let j=0;j<4;j++){const x=(j-1.5)*w*.20;box(internal,x,-hgt*.06,l*.408,w*.185,hgt*.64,l*.13,black,'battery');box(internal,x,hgt*.277,l*.408,w*.177,beam*.4,l*.128,bronze,'battery');box(internal,x,hgt*.02,l*.48,w*.1,hgt*.40,beam*.2,aqua,'battery');}for(let j=0;j<5;j++)box(internal,0,-hgt*.33+j*hgt*.13,-l*.41,w*.76,beam*.7,l*.105,silver,'storage');
for(let i=0;i<4;i++){let a=i*Math.PI/2+Math.PI/4,r=w*.22,g=join(internal,r*Math.cos(a),hgt*.45,r*Math.sin(a),'cmg');g.rotation.z=Math.sin(a)*.55;let rotor=cyl(g,0,0,0,w*.103,w*.103,beam*.7,bronze,'cmg');let ring=new T.Mesh(new T.TorusGeometry(w*.114,beam*.19,6,20),ivory);ring.rotation.x=.4;g.add(ring);cmgs.push({g,rotor,a});}for(let s of [-1,1]){const engine=join(root,s*w*.28,-hgt*.21,-l*.53,'propulsion');let bell=cyl(engine,0,0,-w*.10,w*.080,w*.15,w*.25,dark,'propulsion',24,true);bell.rotation.x=Math.PI/2;let rim=cyl(engine,0,0,-w*.236,w*.151,w*.151,beam*.22,bronze,'propulsion',24,true);rim.rotation.x=Math.PI/2;const plume=new T.Mesh(new T.ConeGeometry(w*.125,w*1.7,18,1,true),new T.MeshBasicMaterial({color:0x6ccaff,transparent:true,opacity:.43,side:T.DoubleSide,depthWrite:false}));plume.position.z=-w*1.06;plume.rotation.x=-Math.PI/2;engine.add(plume);plumes.push(plume);}
return{root,internal,skin,wings,rads,cmgs,cells,leds,dish,optic,patches,plumes,bw,bh,bl,wingspan:2*panelL+1.86*bw,spanZ:2*radL+bl+.7*bw};}
